def _text(path):
    doc = Document(path)
    chunks = [p.text for p in doc.paragraphs]
    for table in doc.tables:
        for row in table.rows:
            chunks.append(" | ".join(cell.text for cell in row.cells))
    return "\n".join(chunks).lower()

def _has_number(text, value, tolerance=0.11):
    # Accept ordinary thousands separators such as 1,000 in rendered DOCX tables.
    for token in re.findall(r"(?<![\w.])-?(?:\d{1,3}(?:,\d{3})+|\d+(?:\.\d+)?)", text):
        try:
            if abs(float(token.replace(",", "")) - value) <= tolerance:
                return True
        except ValueError:
            pass
    return False

def check_memo_artifact(ws):
    path = Path(ws) / "04_executive_implementation/SHMC_December_2025_Intervention_Gap_Action_Memo.docx"
    if not path.exists():
        return {"score": 0, "detail": "required December action memo DOCX is missing"}
    try:
        text = _text(path)
    except Exception as exc:
        return {"score": 0, "detail": f"cannot read DOCX: {exc}"}
    checks = [("ahcp", 881, 1000, 88.1, 91.5, "rebecca langford"), ("follow", 711, 1000, 71.1, 76.5, "graham prescott"), ("medication", 924, 1000, 92.4, 94.5, "lillian park"), ("red", 803, 1000, 80.3, 84.5, "alicia moreno")]
    missing = []
    for label, numerator, denominator, rate, target, owner in checks:
        if label not in text or not _has_number(text, numerator, 0.01) or not _has_number(text, denominator, 0.01):
            missing.append(f"{label} counts/label")
        if not _has_number(text, rate) or not _has_number(text, target) or owner not in text:
            missing.append(f"{label} rate/target/owner")
    if "december" not in text or "2025" not in text:
        missing.append("December 2025 reporting period")
    if missing:
        return {"score": 0, "detail": "missing required memo evidence: " + ", ".join(missing)}
